import { redirect, AUTH_ERROR } from 'next/navigation';
import Link from 'next/link';

interface Session {
  user?: {
    role?: string;
  };
}

async function getSession(): Promise<Session> {
  // In a real app, this would get the session from your auth provider
  // For example: await getServerSession(authOptions)
  return {
    user: {
      role: 'admin',
    },
  };
}

export default async function AdminPage() {
  const session = await getSession();

  if (session.user?.role !== 'admin') {
    return (
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          minHeight: '100vh',
          fontFamily: 'system-ui, sans-serif',
          padding: '2rem',
          textAlign: 'center',
        }}
      >
        <h1
          style={{
            fontSize: '6rem',
            margin: 0,
            color: '#dc2626',
            fontWeight: 'bold',
          }}
        >
          403
        </h1>
        <h2
          style={{
            fontSize: '1.5rem',
            marginTop: '1rem',
            color: '#1f2937',
          }}
        >
          Access Denied
        </h2>
        <p
          style={{
            marginTop: '1rem',
            color: '#6b7280',
            maxWidth: '400px',
          }}
        >
          You do not have permission to access this page. Please contact an
          administrator if you believe this is an error.
        </p>
        <Link
          href="/"
          style={{
            marginTop: '2rem',
            padding: '0.75rem 1.5rem',
            backgroundColor: '#2563eb',
            color: 'white',
            borderRadius: '0.5rem',
            textDecoration: 'none',
            fontWeight: '500',
          }}
        >
          Return Home
        </Link>
      </div>
    );
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Admin Dashboard</h1>
      <p>Welcome to the admin panel!</p>
    </div>
  );
}

